For those like me who're still stuck on v4, you still can use refs (And keepmounted if the problem occurs in a Dialog)  
```js
import {
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogContentText,
  DialogTitle,
} from '@material-ui/core'
import { Warning } from '@material-ui/icons'
import React, {
  createContext,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react'
import { useTranslation } from 'react-i18next'

const AlertContext = createContext()

function AlertProvider({ children }) {
  const { t } = useTranslation()
  const [open, setOpen] = useState(false)
  const [alert, setAlert] = useState('')
  const buttonRef = useRef()

  const handleClose = () => {
    setOpen(false)
    setAlert('')
  }

  const popAlert = (newAlert = '') => {
    setAlert(newAlert)
    setOpen(true)
  }

  useEffect(() => {
    if (open) {
      buttonRef.current.focus()
    }
  }, [open])

  const values = useMemo(
    () => ({
      popAlert,
    }),
    [],
  )

  return (
    <AlertContext.Provider value={values}>
      {children}
      <Dialog
        keepMounted
        open={open}
        aria-labelledby="alert-dialog-title"
        aria-describedby="alert-dialog-description"
      >
        <DialogTitle id="alert-dialog-title">
          <Warning />
          {t('warning')}
        </DialogTitle>
        <DialogContent>
          <DialogContentText id="alert-dialog-description">
            {alert}
          </DialogContentText>
        </DialogContent>
        <DialogActions>
          <Button ref={buttonRef} onClick={handleClose}>
            {t('common.confirm.dialog.button.ok')}
          </Button>
        </DialogActions>
      </Dialog>
    </AlertContext.Provider>
  )
}

const useAlert = () => {
  const context = useContext(AlertContext)
  if (context === undefined) {
    throw new Error('useAlert must be used within a AlertProvider')
  }
  return context
}

export { AlertProvider, useAlert }

```

If you are still using the V4. You can set the `disableRipple` as a prop on your button. Or you can set by default on `createTheme`.

`
const theme = createMuiTheme({
    props: {
      MuiButtonBase: {
        disableRipple: true,
      }
    }
  });
  `

If you need the ripple and don't want to upgrade yet then this worked for me in React 18:

```
function FocusRippleButtonReact17({ autoFocus, children, ...other }) {
  const actionRef = React.useRef();

  useLayoutEffect(() => {
    if (actionRef?.current && autoFocus) {
      // Otherwise autoFocus only takes affect for keyboard use and ignores mouse users
      actionRef.current.focusVisible();
    }
  }, [autoFocus]);

  return (
    <Button
      action={actionRef}
      {...other}
    >
      {children}
    </Button>
  );
}

function FocusRippleButton(props) {
  const { autoFocus } = props;
  const ref = React.useRef();

  useEffect(() => {
    if (ref?.current && autoFocus) {
      // See https://github.com/mui/material-ui/issues/30953 for why must use React 17 render for this component and MUI < 5
      ReactDOM.render(<FocusRippleButtonReact17 {...props} />, ref.current);
    }
  }, [ref, autoFocus, props])

  if (!autoFocus) {
    return <FocusRippleButtonReact17 {...props} />;
  }

  return (
    <div ref={ref}></div>
  );
}

export default FocusRippleButton;
```
